"""Install cut frames into the site: copy images to public/frames, write src/app/frames.css and
src/lib/frames.ts from frames.json.

usage: python install_frames.py CUT_DIR FRONTEND_DIR
"""
import json
import shutil
import sys
from pathlib import Path

cut, fe = Path(sys.argv[1]), Path(sys.argv[2])
meta = json.loads((cut / "frames.json").read_text())
dest = fe / "public" / "frames"
dest.mkdir(parents=True, exist_ok=True)
SCALE = 0.5  # drawn at half the source thickness: 1:1 pixels on 2x (Retina/phone) screens

css = [
    "/* GENERATED by install_frames.py from the frame sheet: one class per frame.",
    "   Each frame image is 9-sliced around the painting (corners kept, edges repeated).",
    "   --fw is the drawn thickness on desktop; .salon scales it down on smaller screens. */",
]
names = []
total = 0
for m in meta:
    key = m["name"].replace("-", "_")  # Strapi enum values can't contain hyphens
    names.append(key)
    src = cut / f"{m['name']}.webp"
    shutil.copyfile(src, dest / f"{key}.webp")
    total += src.stat().st_size
    s = m["slice"][0]
    css.append(
        f".frame-{key} {{ --fw: {round(s * SCALE, 1)}px; }}\n"
        f".frame-{key}::before {{ border-image: url('/frames/{key}.webp') {s} round; }}"
    )
(fe / "src" / "app" / "frames.css").write_text("\n".join(css) + "\n")
(fe / "src" / "lib" / "frames.ts").write_text(
    "// GENERATED by install_frames.py: the textured frames available on the salon wall.\n"
    "// Keep in sync with the `frame` enumeration in the backend product schema.\n"
    f"export const FRAME_NAMES = {json.dumps(names, indent=2)} as const;\n"
)
print(len(names), "frames,", round(total / 1024), "KB total")
print(json.dumps(["auto", "none"] + names))
